module find_black_square (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] grid_packed,   // 8x8 grid, row-major, bit 0 = (0,0)\n    output reg [3:0] row_center,     // 1-indexed row (max 8)\n    output reg [3:0] col_center,     // 1-indexed column (max 8)\n    output reg done\n);\n\n// States\nlocalparam [1:0] IDLE     = 2'b00;\nlocalparam [1:0] SCANNING = 2'b01;\nlocalparam [1:0] DONE_ST  = 2'b10;\n\n// Registers\nreg [1:0] state;\nreg [5:0] idx;              // 0 to 63\nreg [2:0] min_row, max_row; // 0-7\nreg [2:0] min_col, max_col; // 0-7\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        idx <= 6'd0;\n        min_row <= 3'd7;\n        max_row <= 3'd0;\n        min_col <= 3'd7;\n        max_col <= 3'd0;\n        row_center <= 4'd0;\n        col_center <= 4'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= SCANNING;\n                    idx <= 6'd0;\n                    min_row <= 3'd7;\n                    max_row <= 3'd0;\n                    min_col <= 3'd7;\n                    max_col <= 3'd0;\n                end\n            end\n\n            SCANNING: begin\n                // Process current index\n                if (grid_packed[idx]) begin\n                    if (idx[5:3] < min_row) min_row <= idx[5:3];\n                    if (idx[5:3] > max_row) max_row <= idx[5:3];\n                    if (idx[2:0] < min_col) min_col <= idx[2:0];\n                    if (idx[2:0] > max_col) max_col <= idx[2:0];\n                end\n\n                // Advance index\n                if (idx >= 6'd63) begin\n                    state <= DONE_ST;\n                end else begin\n                    idx <= idx + 6'd1;\n                end\n            end\n\n            DONE_ST: begin\n                // Compute center (1-indexed)\n                row_center <= (min_row + max_row) / 2 + 4'd1;\n                col_center <= (min_col + max_col) / 2 + 4'd1;\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\nendmodule